insert into public.quests (id, world, moon_phase, title, description, xp, kind) values
('body-01', 'body', 'new', 'Fill your bottle first', 'Before anything else today, fill a water bottle and keep it where you can see it. That is the whole intention.', 10, 'simple'),
('body-02', 'body', 'new', 'Pick a bedtime', 'Choose a time to put your phone down tonight. Before 11pm is a good start. Write it somewhere you will see it.', 10, 'simple'),
('body-03', 'body', 'waxing', 'Ten-minute walk', 'Walk for ten minutes. Round the block, to the boutik, along the beach. Music optional, no pace required.', 15, 'simple'),
('body-04', 'body', 'waxing', 'Three glasses before lunch', 'Drink three glasses of water before midday. Tea counts if it is not too sweet.', 10, 'simple'),
('body-05', 'body', 'waxing', 'Dance to one song', 'Put on one song you love and move to it. Sega, afrobeats, anything. Door closed is fine.', 15, 'simple'),
('body-06', 'body', 'full', 'Walk with someone', 'Ask a friend, a cousin or your mum to walk with you for ten minutes. Talking is allowed.', 15, 'simple'),
('body-07', 'body', 'full', 'Moonlight stretch', 'Step outside or open a window tonight. Reach up, roll your shoulders, touch your toes. Five slow minutes.', 10, 'simple'),
('body-08', 'body', 'waning', 'Sleep before 11', 'Tonight, lights out before 11pm. Put the phone across the room so it is not the last thing you see.', 15, 'simple'),
('body-09', 'body', 'waning', 'Slow stretch', 'Five minutes of gentle stretching: neck, shoulders, back, legs. Breathe out as you lean in.', 10, 'simple'),
('body-10', 'body', 'waning', 'A proper rest', 'Take fifteen minutes doing nothing useful. Lie down, look at the ceiling, listen to the rain.', 10, 'simple'),
('mind-01', 'mind', 'new', 'One line for this month', 'Write one line about what you want this moon cycle to feel like. Not a goal. A feeling.', 15, 'journal'),
('mind-02', 'mind', 'new', 'How are you, honestly?', 'Check in with yourself. No right answer, nobody else sees it.', 10, 'mood'),
('mind-03', 'mind', 'waxing', 'One minute of breathing', 'Sixty seconds. Breathe in as the circle grows, out as it shrinks. That is all.', 10, 'breathe'),
('mind-04', 'mind', 'waxing', 'Mood check-in', 'Pick the face that is closest to how today feels. Lalin keeps a week of them for you.', 10, 'mood'),
('mind-05', 'mind', 'waxing', 'One good thing', 'Write down one good thing from today. Small counts: a mango, a joke, a cool breeze.', 15, 'journal'),
('mind-06', 'mind', 'full', 'Full moon check-in', 'The moon is full. How full do you feel? Pick a face.', 10, 'mood'),
('mind-07', 'mind', 'full', 'Someone you are glad exists', 'Write the name of one person you are glad is in your life, and one word for why.', 15, 'journal'),
('mind-08', 'mind', 'waning', 'Breathe it out', 'One minute of slow breathing before you sleep. Let the day go with each breath out.', 10, 'breathe'),
('mind-09', 'mind', 'waning', 'Let one thing go', 'Write one thing you are ready to stop worrying about this week. Then close the app.', 15, 'journal'),
('mind-10', 'mind', 'waning', 'Quiet check-in', 'How is your mood as the moon gets smaller? Pick a face.', 10, 'mood'),
('glow-01', 'glow', 'new', 'One thing you like about you', 'Say it out loud, or in your head if your little brother is listening. Not about looks. About you.', 15, 'simple'),
('glow-02', 'glow', 'new', 'Name one brave thing', 'Decide on one slightly brave thing you will do this cycle. You do not have to tell anyone.', 15, 'simple'),
('glow-03', 'glow', 'waxing', 'Ask one question', 'Ask a question in class or at work today. The one you were going to keep to yourself.', 20, 'simple'),
('glow-04', 'glow', 'waxing', 'Try something new', 'Try one new thing today: a new route home, a dish at the market, a word in a new language.', 15, 'simple'),
('glow-05', 'glow', 'waxing', 'Say no, kindly', 'If something does not feel right today, say no without saying sorry three times.', 20, 'simple'),
('glow-06', 'glow', 'full', 'Compliment someone', 'Tell someone something you genuinely like about them. Their idea, their laugh, how they helped.', 15, 'simple'),
('glow-07', 'glow', 'full', 'Share a small win', 'Tell a friend about one thing you did well this month. Bragging slightly is allowed.', 15, 'simple'),
('glow-08', 'glow', 'waning', 'Thank past you', 'Think of something hard you got through this year. Say thanks to the girl who did it.', 15, 'simple'),
('glow-09', 'glow', 'waning', 'Unfollow one account', 'Unfollow or mute one account that makes you feel worse after scrolling. Nobody is notified.', 15, 'simple'),
('glow-10', 'glow', 'waning', 'Speak to yourself like a friend', 'Catch one harsh thought about yourself today and rewrite it the way you would say it to a friend.', 20, 'simple'),
('learn-01', 'learn', 'new', 'Myth or Fact: sleep', 'Five quick cards, a few about sleep. Swipe right for fact, left for myth.', 15, 'cards'),
('learn-02', 'learn', 'new', 'Myth or Fact: studies and work', 'Five quick cards, a few about studying and work. Swipe right for fact, left for myth.', 15, 'cards'),
('learn-03', 'learn', 'waxing', 'Myth or Fact: your body', 'Five quick cards, a few about growing up and how bodies change. Swipe right for fact, left for myth.', 15, 'cards'),
('learn-04', 'learn', 'waxing', 'Myth or Fact: health', 'Five quick cards, a few about everyday health. Swipe right for fact, left for myth.', 15, 'cards'),
('learn-05', 'learn', 'waxing', 'Myth or Fact: the ocean', 'Five quick cards, a few about the lagoon and what lives in it. Swipe right for fact, left for myth.', 15, 'cards'),
('learn-06', 'learn', 'full', 'Myth or Fact: online', 'Five quick cards, a few about staying safe online. Swipe right for fact, left for myth.', 15, 'cards'),
('learn-07', 'learn', 'full', 'Myth or Fact: the reef', 'Five quick cards, a few about coral and Mauritian seas. Swipe right for fact, left for myth.', 15, 'cards'),
('learn-08', 'learn', 'waning', 'Myth or Fact: stress', 'Five quick cards, a few about stress and feelings. Swipe right for fact, left for myth.', 15, 'cards'),
('learn-09', 'learn', 'waning', 'Myth or Fact: rest', 'Five quick cards, a few about sleep and rest. Swipe right for fact, left for myth.', 15, 'cards'),
('learn-10', 'learn', 'waning', 'Myth or Fact: screens', 'Five quick cards, a few about phones and the internet. Swipe right for fact, left for myth.', 15, 'cards')
insert into public.myth_cards (id, category, statement, is_myth, explanation) values
('m01', 'sleep', 'Teenagers naturally tend to feel sleepy later at night than adults.', false, 'Fact. During the teen years the body clock shifts later, which is why 10pm can feel early. A regular bedtime helps.'),
('m02', 'sleep', 'Scrolling in bed helps you fall asleep faster.', true, 'Myth. Bright screens and busy feeds keep the brain alert. Putting the phone down a little before bed usually helps.'),
('m03', 'sleep', 'You can fully "catch up" on a whole week of short sleep on Sunday.', true, 'Myth. A lie-in helps a bit, but regular sleep through the week works much better than one long Sunday.'),
('m04', 'sleep', 'Most people aged 13 to 18 need around 8 to 10 hours of sleep.', false, 'Fact. Sleep experts suggest 8 to 10 hours for teens, and 7 to 9 for young adults.'),
('m05', 'health', 'Feeling thirsty is often one of the first signs you need water.', false, 'Fact. Thirst is your body asking. On hot Mauritian days, sip through the day instead of waiting.'),
('m06', 'health', 'Exercise only counts if it lasts at least an hour.', true, 'Myth. Short bits add up. A ten-minute walk or one song of dancing still does your body good.'),
('m07', 'health', 'Moving your body can lift your mood.', false, 'Fact. Movement releases chemicals in the brain that help you feel calmer and happier.'),
('m08', 'health', 'Sunscreen is only needed on the beach.', true, 'Myth. The sun in Mauritius is strong everywhere, even on cloudy days in Curepipe. Shade and sunscreen help.'),
('m09', 'stress', 'A little stress before an exam can actually help you focus.', false, 'Fact. Some nerves sharpen attention. When stress feels too big or lasts a long time, it is worth talking to someone.'),
('m10', 'stress', 'Talking about your worries makes them worse.', true, 'Myth. Sharing a worry with someone you trust usually makes it feel lighter, not heavier.'),
('m11', 'stress', 'Slow breathing can help calm your body down.', false, 'Fact. Breathing out slowly tells your nervous system that things are okay. Try a minute in the Mind world.'),
('m12', 'stress', 'If you feel sad sometimes, something must be wrong with you.', true, 'Myth. Everyone feels sad sometimes. If it stays for weeks or feels heavy, talk to someone you trust.'),
('m13', 'online', 'Once you delete a photo you sent, it is gone for good.', true, 'Myth. Someone may already have saved or screenshotted it. Only share what you would be okay with others seeing.'),
('m14', 'online', 'Most photos online are edited or filtered in some way.', false, 'Fact. Lighting, filters and editing are everywhere. Comparing yourself to a feed is comparing to something made up.'),
('m15', 'online', 'It is fine to share your passwords with your best friend.', true, 'Myth. Even good friendships change. Keep passwords to yourself and a trusted adult.'),
('m16', 'online', 'You can block and report someone who makes you uncomfortable online.', false, 'Fact. Every major app lets you block and report. You never owe anyone a reply.'),
('m17', 'body', 'Everyone goes through puberty at exactly the same age.', true, 'Myth. Puberty can start anywhere from around 8 to 14, and it moves at its own pace for everyone.'),
('m18', 'body', 'Periods can be irregular for the first year or two.', false, 'Fact. It is common for cycles to take time to settle. If something worries you, a doctor or school nurse can help.'),
('m19', 'body', 'Growing pains and mood changes during the teen years are common.', false, 'Fact. Hormones and growth bring big changes. You are not the only one feeling it.'),
('m20', 'body', 'You should not swim or exercise during your period.', true, 'Myth. You can do whatever feels comfortable. Some people find gentle movement eases cramps.'),
('m21', 'studies', 'Short breaks while studying help you remember more.', false, 'Fact. Studying in blocks with short breaks helps your brain store what you learned.'),
('m22', 'studies', 'Some subjects are only for boys.', true, 'Myth. Maths, coding, engineering, sport, science: there are women leading in all of them, including in Mauritius.'),
('m23', 'studies', 'Asking questions in class means you are not smart.', true, 'Myth. Asking questions is how smart people learn. Often half the class wanted to ask the same thing.'),
('m24', 'studies', 'Sleeping well before an exam helps more than an all-nighter.', false, 'Fact. Sleep is when the brain sorts and saves what you studied.'),
('m25', 'ocean', 'Coral is a plant.', true, 'Myth. Coral is made of tiny animals called polyps, living together with algae that give them their colour.'),
('m26', 'ocean', 'Sea turtles can mistake plastic bags for jellyfish.', false, 'Fact. A floating bag looks a lot like a jellyfish, a turtle favourite. That is one reason beach cleanups matter.'),
('m27', 'ocean', 'Mauritius is almost completely surrounded by a coral reef.', false, 'Fact. A fringing reef rings most of the island, creating the calm lagoons you swim in.'),
('m28', 'ocean', 'Plastic in the sea breaks down completely within a year.', true, 'Myth. Plastic breaks into smaller and smaller pieces called microplastics, which can last for hundreds of years.'),
('m29', 'ocean', 'Coral turns white when the water gets too warm.', false, 'Fact. This is called bleaching. Coral can recover if the water cools down in time.'),
('m30', 'ocean', 'Blue Bay Marine Park is a protected area in Mauritius.', false, 'Fact. Blue Bay Marine Park protects coral gardens with dozens of coral species and many kinds of fish.')
